{"id":239,"path":"backend/app/validation.py","snippet":""""Invoice validation rules (EVA-C-009). Returns issues; empty list = valid.

Deterministic, side-effect free. Totals recomputed from lines (never trust client totals).
"""

from __future__ import annotations

from decimal import ROUND_HALF_UP, Decimal

from .idempiere import readdb

Q = Decimal("0.01")


def _money(x) -> Decimal:
    return Decimal(str(x)).quantize(Q, rounding=ROUND_HALF_UP)


def compute_line(quantity, unit_net_price, vat_rate) -> dict:
    net = _money(Decimal(str(quantity)) * Decimal(str(unit_net_price)))
    vat = _money(net * Decimal(str(vat_rate)))
    return {"net": net, "vat": vat, "gross": net + vat}


def compute_totals(lines: list[dict]) -> dict:
    net = sum((Decimal(str(l["net"])) for l in lines), Decimal("0"))
    vat = sum((Decimal(str(l["vat"])) for l in lines), Decimal("0"))
    return {"net_total": _money(net), "vat_total": _money(vat), "gross_total": _money(net + vat)}

"}
